INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (1,'Speaking','Speaking instructions\r\nYou will answer some questions about yourself and then do three short speaking tasks.\r\n\r\nListen to the instructions and speak clearly into your microphone when you hear the signal.',12,55,70,'[{\"max\": \"10\", \"min\": 0, \"cefr\": \"A1\", \"level\": \"LEVEL 1\", \"description\": \"Needs total guidance\"}, {\"max\": \"20\", \"min\": \"10\", \"cefr\": \"A2\", \"level\": \"LEVEL 2\", \"description\": \"Excellent\"}]','speaking','uploads/modules/mod-1-begin-9d73671c-5985-4f91-abba-ab704f23b718.mp3',30);
INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (2,'Listening','Listening instructions\r\nYou will listen to seventeen recordings.\r\n\r\nClick on the PLAY button to listen to each recording.\r\n\r\nYou can listen to each recording TWO TIMES ONLY.\r\n\r\nYou have 40 minutes to complete the test.\r\n\r\n\r\n\r\nWhen you click on the Start Assessment button, the test will begin.',40,50,150,'[{\"max\": \"5\", \"min\": 0, \"cefr\": \"A1\", \"level\": \"LEVEL 1\", \"description\": \"You can do much more better\"}, {\"max\": \"10\", \"min\": \"5\", \"cefr\": \"A2\", \"level\": \"LEVEL 2\", \"description\": \"Excellent\"}]','listening',NULL,NULL);
INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (3,'Writing','\r\nWriting instructions\r\nThe test has four parts and takes up to 10 minutes.\r\n\r\nRecommended times:\r\n\r\nPart One: 5 minutes\r\n\r\nPart Two: 5 minutes\r\n\r\n\r\n\r\nWhen you click on the \'Start Assessment\' button, the test will begin.',50,50,110,'[]','writing',NULL,NULL);
INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (4,'Reading','Time remaining\r\n\r\nReading instructions\r\nThe test has 1 part.\r\n\r\nTotal Time: 30 minutes.\r\n\r\n\r\n\r\nWhen you click on the start assessment button, the test will begin.',35,50,160,'[{\"max\": \"100\", \"min\": 0, \"cefr\": \"c1\", \"level\": \"LEVEL 3\", \"description\": \"Great job\"}]','reading',NULL,NULL);
INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (5,'Grammar & Vocabulary','\r\nGrammar and Vocabulary instructions\r\nThe test consists of 1 section:\r\n\r\n\r\nTotal Time: 30 minutes\r\n\r\n\r\n\r\nWhen you click on the start assessment button, the test will begin.',25,50,370,'[{\"max\": \"10\", \"min\": 0, \"cefr\": \"A2\", \"level\": \"LEVEL 1\", \"description\": \"Good\"}]','reading',NULL,NULL);
INSERT INTO `modules` (`id`, `name`, `description`, `duration_minutes`, `pass_marks`, `total_marks`, `proficiency_mapping`, `module_type`, `begin_speaking_audio_url`, `speaking_recording_duration`) VALUES (6,'Numeracy','Numeracy instructions\r\nThis test has 1 task.\r\n\r\n\r\nIf a question asks you to type in a result or number, only put in the number. For example, if the answer is 15 metres, type 15. If the answer is $12, only type 12.\r\n\r\nIn the later stages of the test you will see a calculator image in the top right hand of the screen. Click on it to use the calculator. \r\n\r\n\r\nWhen you click on the \'Start Assessment\' button, the test will begin.',75,50,494,'[]','reading',NULL,NULL);
