INSERT INTO `question_options` (`id`, `question_id`, `option_text`, `is_correct`, `explanation`) VALUES (589,219,'44',0,'44 is close to 46, but the sequence increases by +6 each step:  22 ΓåÆ 28 (+6), 28 ΓåÆ 34 (+6), 34 ΓåÆ 40 (+6), 40 ΓåÆ 46 (+6), So the next number should be 46 + 6 = 52, not 44.');
