INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (147,4,'DRAG_DROP_ORDERING','Signs on the coast road\n\n',NULL,NULL,10,1,NULL,'click','{\"items\": [{\"text\": \"For this reason it is easy for them to take a wrong turn and get lost.\", \"order\": 5}, {\"text\": \"These will help visitors to find their way to our beautiful town.\", \"order\": 4}, {\"text\": \"This road is busy during the summer when tourists visit the area.\", \"order\": 3}, {\"text\": \"They donΓÇÖt know the road because many of them are here for the first time.\", \"order\": 2}, {\"text\": \"This is why we think there should be more signs along the road.\", \"order\": 1}], \"drag_items\": [\"Item 1\"], \"drop_zones\": [\"Zone 1\"], \"fixed_sentence\": \"This report gives information about the traffic problems on the coast road.\", \"correct_mapping\": {\"0\": 0}}','a59cc5e5-73f5-47cd-ab24-6d93fef1f522');
