INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (149,4,'DRAG_DROP_ORDERING','Instructions for office visitors\n\n',NULL,NULL,10,1,NULL,'click','{\"items\": [{\"text\": \"A member of staff will write this information in the visitorΓÇÖs book.\", \"order\": 5}, {\"text\": \"Before you leave, please return the card to a member of staff at the front desk.\", \"order\": 4}, {\"text\": \"You can then use the card to enter through the security gate.\", \"order\": 3}, {\"text\": \"Next, he or she will give you a visitorΓÇÖs identity card.\", \"order\": 2}, {\"text\": \"You should go to the front desk upon arrival and give your name and\", \"order\": 1}], \"drag_items\": [\"Item 1\"], \"drop_zones\": [\"Zone 1\"], \"fixed_sentence\": \"If you are visiting our office for the first time, please follow these instructions.\", \"correct_mapping\": {\"0\": 0}}','d7820c64-eca7-4ac5-836a-38614ad64379');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (150,4,'QUESTION_FORM','Four people respond in the comments section of an online magazine article about education and work. Read their comments and answer the questions below.',NULL,NULL,10,0,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (151,4,'QUESTION_FORM','Education and work',NULL,NULL,10,1,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (152,4,'QUESTION_FORM','Person A:\n\nAs you get older, responsibilities like a job and family dominate your life. It can be hard to balance things. Studying at university is demanding. So you should do it at an age when you are independent and carefree. It is also important to learn how the world of business works. Spending unpaid time in a company is a great way to get that experience. Any course that can give you an opportunity to do that is worth considering.',NULL,NULL,10,2,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (153,4,'QUESTION_FORM','Person B:\n\nLife doesnΓÇÖt really get serious until you hit your mid-twenties. Before that, try out different things and get some life experience. ItΓÇÖs only as you approach your thirties that you need to get serious about your career. ThatΓÇÖs the time to start thinking about further education. Many colleges offer inexpensive courses for more mature students. Going back to student life for a year is a great idea and you can then return to the world of work at management level.',NULL,NULL,10,3,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (154,4,'QUESTION_FORM','Person C:\n\nNowadays it is popular for school leavers to take a break before they think about an occupation or a place at university. I think the most important thing is to start working as soon as you can. You need practical experience for your CV and that can be more valuable than a diploma. Nevertheless, your studies do not have to stop just because you are working. Colleges and universities offer options for people who want to do both.',NULL,NULL,10,4,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (155,4,'QUESTION_FORM','Person D:\n\nI think we should all keep learning, but you donΓÇÖt need a piece of paper from an institution to prove it. There are many free courses available online. Of course, not all are good, but a little research will help you identify which one is best for you. A lot of young people get into debt because they have to pay for their studies. With the resources available online these days, you can take control. You wonΓÇÖt regret it.',NULL,NULL,10,5,NULL,'click','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (156,4,'MCQ','1. Who thinks you should study when you are older?',NULL,NULL,10,6,NULL,'select','null','fdc9b08b-83da-41e6-b1e4-71b4d3160443');
