INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (165,4,'MCQ','1. On 3rd June 2010 an international crew of six astronauts entered a space ship and prepared themselves for a 520-day voyage to the planet Mars and back. The module that was to be their home for the next year and a half contained their sleeping quarters, a kitchen/dining room, a living room, a control room and a toilet. There was also space for food storage, a small greenhouse, a bathroom, a sauna and even a gym. The Mars landing was scheduled for 12th February 2011, following a 255-day flight, and would involve a full two days of exploration of the planet surface. An equally long return journey would see the astronauts return to earth on 4th November 2011.',NULL,NULL,10,2,NULL,'select','null','33031e3f-dc4f-420d-b4bc-49da25cca731');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (166,4,'MCQ','2. Emerging from the spaceship after an exhausting 520 days, Russian commander Alexei Sitev declared the mission finally over. \'The programme has been fully carried out,\' he announced at a press conference. \'All the crew members are in good health. We are now ready for further tests.\' Indeed, the general consensus in the scientific community was that the Mars 500 project had achieved its aims, and, what is more, the crew had managed to complete their mission without ever having to leave the EarthΓÇÖs atmosphere.',NULL,NULL,10,3,NULL,'select','null','33031e3f-dc4f-420d-b4bc-49da25cca731');
