INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (180,2,'AUDIO_MCQ','Four people are describing their plans for the future. Complete the sentences below.\nSpeaker A wants to\n','Speaker A:\nIΓÇÖve always loved studying, and I want to continue my education after finishing school. My dream is to go to college and learn more about science.\n\nSpeaker B:\nI really enjoy exploring new cultures and meeting different people. In the future, I would like to work in a different country and gain international experience.\n\nSpeaker C:\nI have many ideas and I like being independent. One day, I want to start a business and build something of my own from the ground up.\n\nSpeaker D:\nFor me, life is about experiences. I want to travel the world, see new places, and maybe even write a book about my journeys later.',NULL,10,0,NULL,'select','null','4053fd1c-ec47-4e75-bfb3-a03305b35696');
