INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (184,2,'AUDIO_MCQ','Listen to two parents discussing the issue of childrenΓÇÖs health. Read the opinions below and decide whose opinion matches the statements, the man, the woman, or both the man and the woman. 1. Parents should better manage their childrenΓÇÖs diets. ','Woman:\nIΓÇÖve been reading about childrenΓÇÖs health, and I think parents should better manage their childrenΓÇÖs diets. Kids eat too much junk food these days.\n\nMan:\nI agree. Diet is important, but I also think parents should support their childΓÇÖs interest in sport. Physical activity really helps their overall development.\n\nWoman:\nThatΓÇÖs true. Along with that, children also need some quiet time. It can really help improve their concentration and focus, especially for schoolwork.\n\nMan:\nAbsolutely. But at the same time, too much rest isnΓÇÖt good either. Excessive sleep can actually be bad for young people if it becomes a habit.\n\nWoman:\nYes, balance is the keyΓÇöhealthy food, regular exercise, enough quiet time, and proper sleep.',NULL,10,0,NULL,'select','null','c5d38e71-ee7c-434c-8f4f-8c329fca08ef');
