INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`) VALUES (188,2,'AUDIO_MCQ','Listen to a city planner talk at a press conference about a new transport plan and answer the questions below.\n\n1. What is the main goal of the new transport plan?','Good morning, everyone. Thank you for attending this press conference. Today, IΓÇÖm here to introduce our new transport plan for the city. The main goal of this plan is to reduce traffic congestion and improve air quality.\n\nWe are planning to expand public transport by adding more buses and introducing two new metro lines. These changes will make it easier for people to travel across the city quickly and efficiently.\n\nIn addition, we will create more cycling lanes and improve pedestrian pathways to encourage eco-friendly travel. This will not only reduce pollution but also promote a healthier lifestyle among residents.\n\nThe project will begin next year and is expected to be completed within five years. We understand that there may be some disruptions during construction, but we will try to minimize inconvenience to the public.\n\nFinally, we are also introducing a smart ticketing system, which will allow passengers to use a single card for all types of transport.\n\nThank you for your attention. IΓÇÖm happy to take any questions now.',NULL,10,0,NULL,'click','null','a72630a0-f87a-4bdf-b698-2d6ecfedf22c');
